/******************************max-768px**********************/

@media (max-width: 768px) {
    .row2 .col-md-2 {
        width: 100%;
    }

    li.DeskTopLogo {
        display: none !important;
    }

    a.aast-mobile {
        display: block;
        width: 100%;
        display: contents;
    }

    a.aast-mobile img {
        display: block;
        width: 60%;
        float: left;
        margin: 0 0 0 25px;
    }

    .ltn__header-top-area {

        text-align: center;
    }

    .ltn__header-top-area .ltn__social-media ul li {
        font-size: 12px;
        margin: 0 5px 0 0;
    }

    .ltn__top-bar-menu .ltn__currency-menu .active-currency,
    .ltn__top-bar-menu > ul > li {
        font-size: 12px;
    }

    .ltn__drop-menu > ul > li {
        position: inherit;
    }

    .ltn__drop-menu > ul > li > a {
        height: 20px;
        line-height: 20px;
    }

    .ltn__drop-menu ul li ul {
        left: 50%;
        right: 50%;
        -webkit-transform: translateX(-50%);
        -ms-transform: translateX(-50%);
        transform: translateX(-50%);
    }

    .top-bar-right {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-pack: justify;
        -ms-flex-pack: justify;
        justify-content: space-between;
    }

    .site-logo {
        min-width: 100px;
    }
}


/******************************max-576px**********************/

@media (max-width:576px) {
    .col-sm-8 {
        width: 70%;
    }

    .col-sm-6 {
        width: 50%;
    }

    .col-sm-12 {
        width: 100%;
    }

    .top-bar-right {
        width: fit-content;
    }

    #menuToggle {
        padding: 0.6em 0.2em 0.4em;
        border-radius: 5px;
    }

    .aast-logo {
        width: 50%;
        left: 0%;
        top: 2em;
    }

    .ltn__header-top-area {
        background-color: #132b61;
    }

    .top-bar-right {
        margin-top: 5em;
    }

    .ltn__top-bar-menu > ul > li {
        margin: 0;
    }

    .col-sm-12 {
        width: 100% !important;
        padding: 10px;
    }
}

